export function titre(initial,final){if(![initial,final].every(Number.isFinite)||initial<0||final>50||final<initial)throw Error('Invalid burette readings');return final-initial;}
export function meanSelected(readings,indices){if(!indices.length||new Set(indices).size!==indices.length||indices.some(i=>!Number.isInteger(i)||i<0||i>=readings.length))throw Error('Choose valid readings');return indices.reduce((s,i)=>s+readings[i],0)/indices.length;}
export const titreTasks=[{initial:.2,final:24.3,rough:25,readings:[24.1,24,24.05],indices:[0,1,2]},{initial:1.1,final:21.2,rough:20.9,readings:[20.1,20,20.6],indices:[0,1]},{initial:.4,final:18.65,rough:18.9,readings:[18.2,18.25,18.3],indices:[0,1,2]}];
export function hydrogenFactor(firstPH,secondPH){if(![firstPH,secondPH].every(n=>Number.isInteger(n)&&n>=0&&n<=14))throw Error('Use whole-number pH in course range');return 10**(secondPH-firstPH);}
export const strengthTasks=[{name:'Hydrochloric acid',c:.01,ionisation:'complete',strength:'strong',relative:'dilute',firstPH:3,secondPH:5},{name:'Ethanoic acid',c:1,ionisation:'partial',strength:'weak',relative:'concentrated',firstPH:2,secondPH:3},{name:'Nitric acid',c:.1,ionisation:'complete',strength:'strong',relative:'same',firstPH:4,secondPH:1}];
